/**
 * Views, menus and task definitions contributed in package.json (generated by `npm run gen`).
 * Pure: no `vscode` import.
 */

export const VIEW_CONTAINERS = {
  panel: [{ id: 'unintellij-git', title: 'Git', icon: 'media/git.svg' }],
};

export const VIEWS = {
  'unintellij-git': [{ type: 'webview', id: 'unintellij.gitLog', name: 'Log' }],
  // In VS Code's Source Control container, whose native views UnIntelliJ hides (see scmViews.ts).
  // Expanded by default: contributed views are otherwise added collapsed at the bottom.
  scm: [{ type: 'webview', id: 'unintellij.commit', name: 'Commit', visibility: 'visible' }],
};

/** Activity bar container command for a container id, used by the keymap. */
export const containerCommand = (id: string): string => `workbench.view.extension.${id}`;

const commitMenu = (section: string, entries: [string, string][], extraWhen = '') =>
  entries.map(([command, group]) => ({ command, group, when: `webviewId == 'unintellij.commit' && webviewSection == '${section}'${extraWhen}` }));
const CHANGELISTS_ON = ' && config.unintellij.vcs.changelists.enabled';

const logMenu = (entries: [string, string][]) => entries.map(([command, group]) => ({ command, group, when: "webviewId == 'unintellij.gitLog' && webviewSection == 'commit'" }));

export const MENUS = {
  'webview/context': [
    ...logMenu([
      ['unintellij.git.copyRevision', '1_copy@1'],
      ['unintellij.git.checkoutRevision', '2_branch@1'],
      ['unintellij.git.newBranchHere', '2_branch@2'],
      ['unintellij.git.newTag', '2_branch@3'],
      ['unintellij.git.cherryPick', '3_change@1'],
      ['unintellij.git.revertCommit', '3_change@2'],
      ['unintellij.git.resetToHere', '3_change@3'],
    ]),
    ...commitMenu('file', [
      ['unintellij.commit.showDiff', '1_diff@1'],
      ['unintellij.commit.jumpToSource', '1_diff@2'],
      ['unintellij.commit.rollback', '2_changes@1'],
    ]),
    ...commitMenu('file', [['unintellij.commit.moveToChangelist', '2_changes@2']], CHANGELISTS_ON),
    ...commitMenu('unversioned', [
      ['unintellij.commit.addToVcs', '1_vcs@1'],
      ['unintellij.commit.jumpToSource', '1_vcs@2'],
      ['unintellij.commit.rollback', '2_delete@1'],
    ]),
    ...commitMenu(
      'changelist',
      [
        ['unintellij.commit.setActiveChangelist', '1_changelist@1'],
        ['unintellij.commit.newChangelist', '1_changelist@2'],
        ['unintellij.commit.renameChangelist', '1_changelist@3'],
        ['unintellij.commit.deleteChangelist', '1_changelist@4'],
      ],
      CHANGELISTS_ON,
    ),
  ],
  'view/title': [
    // IntelliJ's Update / Push / Fetch actions, also on the Commit and Git tool windows.
    ...['unintellij.updateProject', 'unintellij.push', 'unintellij.fetch'].flatMap((command, i) =>
      ['unintellij.commit', 'unintellij.gitLog'].map((view) => ({ command, when: `view == ${view}`, group: `navigation@${10 + i}` })),
    ),
  ],
};

